import SwiftUI
struct SwipeOverlayView: View { let offset: CGSize; let action: SwipeAction?; private var progress: Double { min(1,max(0,(abs(offset.width)-SwipeThresholds.softSwipeOffset)/max(1,SwipeThresholds.hardSwipeOffset-SwipeThresholds.softSwipeOffset))) }; var body: some View { ZStack { if offset.width > SwipeThresholds.softSwipeOffset { HStack { rightLabel; Spacer() }.padding(24).opacity(progress) }; if offset.width < -SwipeThresholds.softSwipeOffset { HStack { Spacer(); ActionLabel(title:"SKIP", systemImage:"xmark", color:DS.ColorToken.textMuted, emphasized:false) }.padding(24).opacity(progress) } }.rotationEffect(.degrees(-offset.width*SwipeThresholds.rotationFactor*0.5)).allowsHitTesting(false) }
    @ViewBuilder private var rightLabel: some View { if action == .apply { ActionLabel(title:"APPLY NOW", systemImage:"checkmark", color:DS.ColorToken.success, emphasized:true) } else if action == .star { ActionLabel(title:"STAR", systemImage:"star.fill", color:DS.ColorToken.gold, emphasized:false) } else { ActionLabel(title:"QUEUE", systemImage:"tray.and.arrow.down", color:DS.ColorToken.primary, emphasized:false) } }
}
